public class Scope_getVar_TriageGen1Test {

    @Test
    public void testGetVar_FoundInCurrentScope() {
        // Arrange
        Scope scope = mock(Scope.class);
        Var expectedVar = mock(Var.class);
        String varName = "testVar";

        when(scope.getVar(varName)).thenReturn(expectedVar);

        // Act
        Var actualVar = scope.getVar(varName);

        // Assert
        assertEquals(expectedVar, actualVar);
    }

    @Test
    public void testGetVar_FoundInParentScope() {
        // Arrange
        Scope parentScope = mock(Scope.class);
        Scope childScope = mock(Scope.class);
        Var expectedVar = mock(Var.class);
        String varName = "parentVar";

        // We need to simulate the behavior of the actual method implementation 
        // Since we cannot mock the method being tested itself, we use a real implementation 
        // or mock the dependencies. However, the method under test is 'getVar'.
        // In a real scenario, Scope is likely a class with concrete logic.
        // To test the logic provided:

        // Mocking the behavior of the logic provided in the prompt:
        // Var var = vars.get(name); -> if null, return parent.getVar(name)

        // Because we are testing the logic of the method itself, we assume 
        // we are testing a subclass or a concrete implementation where we can control 'vars' and 'parent'.
        // Since I cannot modify the source class, I will provide the test logic 
        // assuming a concrete implementation of Scope exists.

        // Let's assume a concrete implementation for the sake of the test logic:
        ScopeImpl scope = new ScopeImpl(null); 
        ScopeImpl parent = new ScopeImpl(null);
        scope.setParent(parent);

