    @Test
    public void testGetVar_NotFoundInCurrentScopeAndNoParent() {
        // Arrange
        ScopeImpl scope = new ScopeImpl(null);

        // Act
        Var actualVar = scope.getVar("nonExistent");

        // Assert
        assertNull(actualVar);
    }

    /**
     * Inner class to facilitate testing the specific logic provided in the prompt,
     * as Scope is an abstract/complex class in the JS compiler.
     */
    private static class ScopeImpl extends Scope {
        private final java.util.Map<String, Var> vars = new java.util.HashMap<>();
        private Scope parent;

        ScopeImpl(Scope parent) {
            this.parent = parent;
        }

        void addVar(String name, Var var) {
            vars.put(name, var);
        }

        void setParent(Scope parent) {
            this.parent = parent;
        }

        @Override
        public Var getVar(String name) {
            Var var = vars.get(name);
            if (var != null) {
                return var;
            } else if (parent != null) {
                return parent.getVar(name);
            } else {
                return null;
            }
        }

        // Stubbing other methods to satisfy the Scope interface/abstract requirements
        @Override public Node getRootNode() { return null; }
        @Override public Scope getParent() { return parent; }
        @Override public StaticScope<JSType> getParentScope() { return null; }
        @Override public ObjectType getTypeOfThis() { return null; }
        @Override public StaticSlot<JSType> getSlot(String name) { return null; }
        @Override public StaticSlot<JSType> getOwnSlot(String name) { return null; }
        @Override public Var getArgumentsVar() { return null; }
        @Override public boolean isDeclared(String name, boolean recurse) { return false; }
        @Override public java.util.Iterator<Var> getVars() { return null; }
        @Override public Iterable<Var> getReferences(Var var) { return null; }
        @Override public StaticScope<JSType> getScope(Var var) { return null; }
        @Override public Iterable<Var> getAllSymbols() { return null; }
        @Override public int getVarCount() { return 0; }
        @Override public boolean isGlobal() { return false; }
        @Override public boolean isLocal() { return false; }
        @Override public java.util.Iterator<Var> getDeclarativelyUnboundVarsWithoutTypes() { return null; }
